+const { READ, WRITE, ADMIN, toggleRight } = require('../src/rights');
+const { transferOwnership, OWNER } = require('../src/ownership');
+
+test('a switch turns a right on', () => {
+  assert.strictEqual(toggleRight(READ, WRITE), READ | WRITE);
+});
+
+test('the new owner gets every right', () => {
+  const doc = { owner: 'ana', shares: { ana: OWNER, ben: READ } };
